/* From Uiverse.io by Javierrocadev - Tags: hover, card animation, article */
.__UIV_SCOPE__ .card {
  width: 300px;
  height: 325px;
  background: #e8e8e8;
  border-radius: 15px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
  color: #212121;
  border: 2px solid #ab4b38;
  transition: all .5s ease;
}

.__UIV_SCOPE__ .icons {
  display: flex;
  flex-direction: row;
  gap: 5px;
  position: absolute;
  right: 15px;
  top: 15px;
  transition: opacity 0.5s ease;
  opacity: 0;
}

.__UIV_SCOPE__ .image {
  width: 300px;
  height: 148px;
  background: rgb(223,235,56);
  background: rgb(56,235,226);
  background: linear-gradient(163deg, rgba(56,235,226,1) 0%, rgba(134,221,245,1) 50%);
}

.__UIV_SCOPE__ .save {
  background: #eb4b38;
  color: white;
  border: none;
  border-radius: 5px;
}

.__UIV_SCOPE__ .see-more {
  background: #ab4b38;
  border: none;
  border-radius: 5px;
  color: white;
}

.__UIV_SCOPE__ .save, .__UIV_SCOPE__ .see-more {
  display: flex;
  flex-direction: row;
  justify-content: center;
  gap: 5px;
  padding: 5px;
}

.__UIV_SCOPE__ .save__icon, .__UIV_SCOPE__ .see-more__icon {
  width: 15px;
  fill: white;
}

.__UIV_SCOPE__ .card__info {
  display: flex;
  flex-direction: column;
  flex-grow: 1;
  justify-content: center;
  padding: 15px;
  gap: 3px;
}

.__UIV_SCOPE__ .page {
  font-size: 13px;
  font-weight: 100;
}

.__UIV_SCOPE__ .title {
  text-decoration: none;
  font-weight: 600;
  font-size: 17px;
  color: black;
}

.__UIV_SCOPE__ .content {
  font-size: 14px;
}

.__UIV_SCOPE__ .card:hover {
  box-shadow: 5px 5px 10px 0px #ab4b3866;
}

.__UIV_SCOPE__ .card:hover .icons {
  z-index: 1;
  opacity: 1;
}

.__UIV_SCOPE__ .card:hover .image {
  filter: brightness(.8);
}

.__UIV_SCOPE__ .card:hover .title {
  color: #ab4b38;
}
